 function exportCsv(){const escape=(v:string)=>'"'+v.replaceAll('"','""')+'"';const lines=[["Date","Description","Type","Catégorie","Montant MAD"].join(";"),...entries.map(e=>[new Date(e.date).toLocaleDateString("fr-FR"),escape(e.label),e.type,escape(e.category),e.amount.toFixed(2)].join(";"))];const blob=new Blob(["\uFEFF"+lines.join("\r\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="mizan-transactions.csv";a.click();URL.revokeObjectURL(url)}
