 const currentMonthExpenses=useMemo(()=>{const now=new Date();return entries.filter(e=>{const d=new Date(e.date);return e.type==="expense"&&d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear()})},[entries,customCategories]);
