 const insights=useMemo(()=>{const now=new Date(),year=now.getFullYear(),month=now.getMonth(),day=now.getDate(),days=new Date(year,month+1,0).getDate();const rows=entries.filter(e=>{const d=new Date(e.date);return d.getFullYear()===year&&d.getMonth()===month});const sum=(type:"income"|"expense")=>rows.filter(e=>e.type===type).reduce((n,e)=>n+e.amount,0);const monthIncome=sum("income"),monthExpense=sum("expense");const savingsThisMonth=savingsMovements.filter(m=>m.occurred_on.slice(0,7)===`${year}-${String(month+1).padStart(2,"0")}`&&m.affects_balance).reduce((n,m)=>n+(m.kind==="withdrawal"?-m.amount:m.amount),0);const budgetWarnings=budgets.map(b=>{const used=rows.filter(e=>e.type==="expense"&&e.category===b.category).reduce((n,e)=>n+e.amount,0);return {...b,used,ratio:b.monthly_limit>0?used/b.monthly_limit:0}}).filter(b=>b.ratio>=0.8).sort((a,b)=>b.ratio-a.ratio);const due=recurring.filter(r=>r.active&&r.type==="expense"&&r.day_of_month>=day&&r.day_of_month<=Math.min(days,day+5));const categoryTotals=rows.filter(e=>e.type==="expense").reduce((acc,e)=>{acc[e.category]=(acc[e.category]??0)+e.amount;return acc},{} as Record<string,number>);const topCategory=Object.entries(categoryTotals).sort((a,b)=>b[1]-a[1])[0]??null;const remaining=days-day;const projectedExpense=day>0?monthExpense/day*days:monthExpense;const projectedBalance=availableBalance-Math.max(0,projectedExpense-monthExpense);return {monthIncome,monthExpense,savingsThisMonth,budgetWarnings,due,topCategory,remaining,projectedExpense,projectedBalance,day,days,hasData:rows.length>0};},[entries,budgets,recurring,savingsMovements,availableBalance]);
